// Use defaultSettings from shared schema
const defaultSettings = defaultBatchConfigSettings;

// ─── Series-panel bridge helpers ──────────────────────────────────────────────
// Convert BatchConfigSettings flat fields → SeriesConfig and back.
// The `prefix` is the settings key prefix (e.g. 'width' for widthSeriesItems, etc.)

function getBatchSeriesConfig(settings: BatchConfigSettings, prefix: string): SeriesConfig {
  const s = settings as any;
  return {
    items: s[prefix + 'SeriesItems'] ?? [{ mode: 'fixed', value: 0 }],
    stagingMode: s[prefix + 'SeriesStagingMode'] || 'fixed',
    selection: s[prefix + 'SeriesSelection'] || 'sequential',
    exhaustion: s[prefix + 'SeriesExhaustion'] || 'cycle',
    driver: s[prefix + 'SeriesDriver'] || 'shape-index',
  };
}

function updateBatchSeriesConfig(
  prefix: string,
  handleUpdate: (updates: Partial<BatchConfigSettings>) => void,
  config: SeriesConfig
): void {
  handleUpdate({
    [prefix + 'SeriesItems']: config.items,
    [prefix + 'SeriesStagingMode']: config.stagingMode,
    [prefix + 'SeriesSelection']: config.selection,
    [prefix + 'SeriesExhaustion']: config.exhaustion,
    [prefix + 'SeriesDriver']: config.driver,
  } as any);
}
