                                                  <NumericInput value={currentSettings.strokeSquiggleNoiseFreqRange?.[1] ?? 5} onChange={(v) => handleSettingsUpdate({ strokeSquiggleNoiseFreqRange: [currentSettings.strokeSquiggleNoiseFreqRange?.[0] ?? 0.5, v] })} min={0.1} step={0.1} className="h-9 bg-slate-700 border-slate-600 text-slate-300" />
