                                              <NumericInput value={currentSettings.strokeSquiggleJitterSeedRange?.[1] ?? 100} onChange={(v) => handleSettingsUpdate({ strokeSquiggleJitterSeedRange: [currentSettings.strokeSquiggleJitterSeedRange?.[0] ?? 0, Math.round(v)] })} min={0} step={1} className="h-9 bg-slate-700 border-slate-600 text-slate-300" />
