                                              {currentSettings.strokeSquiggleJitterSeedModulationEnabled && <BufferedSliderWithNumericInput inputUnbounded value={currentSettings.strokeSquiggleJitterSeedModulationValue ?? 9999} onValueCommit={(v) => handleSettingsUpdate({ strokeSquiggleJitterSeedModulationValue: Math.round(v) })} min={1} max={9999} step={1}  inputClassName="h-9 bg-slate-700 border-slate-600 text-slate-300" sliderClassName="flex-1 [&_[role=slider]]:bg-cyan-600" />}
